{"cmd":"cat > /root/output/js/visualization.js <<'JS'
const width = 640;
const height = 520;
const svg = d3
  .select("#bubble-chart")
  .attr("viewBox", `0 0 ${width} ${height}`)
  .attr("preserveAspectRatio", "xMidYMid meet");

const tooltip = d3.select("#tooltip");
const tableBody = d3.select("#stock-table tbody");

let bubbleSelection = null;
let tableSelection = null;
let selectedTicker = null;

const formatCap = (value) => {
  if (!Number.isFinite(value)) return "—";
  const abs = Math.abs(value);
  const f = d3.format(".2f");
  if (abs >= 1e12) return `${f(value / 1e12)}T`;
  if (abs >= 1e9) return `${f(value / 1e9)}B`;
  if (abs >= 1e6) return `${f(value / 1e6)}M`;
  if (abs >= 1e3) return `${f(value / 1e3)}K`;
  return d3.format(",")(value);
};

const formatPrice = d3.format("$.2f");

const lastClose = (rows) => {
  if (!rows || rows.length === 0) return Number.NaN;
  const last = rows[rows.length - 1];
  const close = +last.Close;
  return Number.isFinite(close) ? close : Number.NaN;
};

const loadHistory = (ticker) => {
  const primaryPath = `data/indiv-stock/${ticker}.csv`;
  const fallbackPath = `data/indiv-stock/${ticker.toLowerCase()}.csv`;
  return d3
    .csv(primaryPath)
    .then((rows) => ({ ticker, latestClose: lastClose(rows) }))
    .catch(() =>
      d3
        .csv(fallbackPath)
        .then((rows) => ({ ticker, latestClose: lastClose(rows) }))
        .catch(() => ({ ticker, latestClose: Number.NaN }))
    );
};

const showTooltip = (event, d) => {
  if (d.isEtf) return;
  const lines = [
    `<div class="tip-title">${d.ticker}</div>`,
    `<div class="tip-name">${d.fullName}</div>`,
    `<div class="tip-meta">Sector: ${d.sector}</div>`,
  ];
  if (Number.isFinite(d.latestClose)) {
    lines.push(`<div class="tip-meta">Latest close: ${formatPrice(d.latestClose)}</div>`);
  }
  tooltip
    .html(lines.join(""))
    .classed("visible", true)
    .style("left", `${event.pageX + 12}px`)
    .style("top", `${event.pageY - 20}px`);
};

const moveTooltip = (event, d) => {
  if (d.isEtf) return;
  tooltip
    .style("left", `${event.pageX + 12}px`)
    .style("top", `${event.pageY - 20}px`);
};

const hideTooltip = (d) => {
  if (d.isEtf) return;
  tooltip.classed("visible", false);
};

const selectTicker = (ticker) => {
  selectedTicker = ticker;
  if (bubbleSelection) {
    bubbleSelection.classed("selected", (d) => d.ticker === selectedTicker);
  }
  if (tableSelection) {
    tableSelection.classed("selected", (d) => d.ticker === selectedTicker);
  }
};

const buildLegend = (sectors, colorScale) => {
  const legend = d3.select("#legend");
  const items = legend.selectAll("div.legend-item").data(sectors, (d) => d);

  const itemsEnter = items
    .enter()
    .append("div")
    .attr("class", "legend-item");

  itemsEnter.append("span").attr("class", "legend-swatch");
  itemsEnter.append("span").attr("class", "legend-label");

  const merged = itemsEnter.merge(items);
  merged.select(".legend-swatch").style("background", (d) => colorScale(d));
  merged.select(".legend-label").text((d) => d);

  items.exit().remove();
};

const renderTable = (rows) => {
  const tableRows = tableBody
    .selectAll("tr")
    .data(rows, (d) => d.ticker)
    .join(
      (enter) => {
        const tr = enter.append("tr").attr("class", "stock-row");
        tr.append("td").attr("class", "cell-ticker");
        tr.append("td").attr("class", "cell-name");
        tr.append("td").attr("class", "cell-sector");
        tr.append("td").attr("class", "cell-cap");
        return tr;
      }
    );

  tableRows.select(".cell-ticker").text((d) => d.ticker);
  tableRows.select(".cell-name").text((d) => d.fullName);
  tableRows.select(".cell-sector").text((d) => d.sector);
  tableRows.select(".cell-cap").text((d) => formatCap(d.marketCap));

  tableRows.on("click", (event, d) => {
    event.stopPropagation();
    selectTicker(d.ticker);
  });

  tableSelection = tableRows;
  selectTicker(selectedTicker);
};

const renderBubbles = (nodes, colorScale) => {
  const bubbles = svg
    .selectAll("g.bubble")
    .data(nodes, (d) => d.ticker)
    .join((enter) => {
      const g = enter.append("g").attr("class", "bubble");
      g.append("circle");
      g.append("text");
      return g;
    });

  bubbles
    .select("circle")
    .attr("r", (d) => d.radius)
    .attr("fill", (d) => colorScale(d.sector));

  bubbles.select("text").text((d) => d.ticker).style("font-size", (d) => `${Math.max(10, d.radius * 0.45)}px`);

  bubbles.attr("transform", (d) => `translate(${d.x},${d.y})`);

  bubbles
    .on("mouseover", (event, d) => showTooltip(event, d))
    .on("mousemove", (event, d) => moveTooltip(event, d))
    .on("mouseout", (_, d) => hideTooltip(d))
    .on("click", (event, d) => {
      event.stopPropagation();
      selectTicker(d.ticker);
    });

  bubbleSelection = bubbles;
  selectTicker(selectedTicker);
};

const computeNodes = (data) => {
  const marketCaps = data.filter((d) => Number.isFinite(d.marketCap)).map((d) => d.marketCap);
  const minCap = d3.min(marketCaps);
  const maxCap = d3.max(marketCaps);
  const rScale = d3.scaleSqrt().domain([minCap, maxCap]).range([14, 52]);
  const uniformRadius = 20;

  const sorted = data
    .slice()
    .sort((a, b) => d3.ascending(a.sector, b.sector) || d3.ascending(a.ticker, b.ticker));

  const cols = 8;
  const rows = Math.ceil(sorted.length / cols);

  return sorted.map((d, i) => {
    const col = i % cols;
    const row = Math.floor(i / cols);
    const x = ((col + 0.5) / cols) * width;
    const y = ((row + 0.5) / rows) * height;
    const radius = d.isEtf ? uniformRadius : rScale(d.marketCap);
    return {
      ...d,
      radius,
      x,
      y,
      vx: 0,
      vy: 0,
    };
  });
};

const runSimulation = (nodes, sectorPositions) => {
  const simulation = d3
    .forceSimulation(nodes)
    .force(
      "x",
      d3
        .forceX((d) => sectorPositions.get(d.sector).x)
        .strength(0.08)
    )
    .force(
      "y",
      d3
        .forceY((d) => sectorPositions.get(d.sector).y)
        .strength(0.08)
    )
    .force("collide", d3.forceCollide((d) => d.radius + 1.5).iterations(2))
    .force("charge", d3.forceManyBody().strength(-6));

  simulation.stop();
  for (let i = 0; i < 300; i += 1) {
    simulation.tick();
  }
};

const render = (data) => {
  const sectors = Array.from(new Set(data.map((d) => d.sector))).sort();
  const palette = [
    "#1f6f8b",
    "#f4a261",
    "#2a9d8f",
    "#e76f51",
    "#8ab17d",
    "#264653",
    "#bc6c25",
    "#607d8b",
    "#c97b63",
    "#4c956c",
    "#b08968",
    "#588157",
    "#6d597a",
  ];
  const colorScale = d3.scaleOrdinal(sectors, palette);

  const nodes = computeNodes(data);
  const ringRadius = Math.min(width, height) * 0.22;
  const angleStep = (2 * Math.PI) / sectors.length;
  const sectorPositions = new Map(
    sectors.map((sector, i) => [
      sector,
      {
        x: width / 2 + ringRadius * Math.cos(angleStep * i),
        y: height / 2 + ringRadius * Math.sin(angleStep * i),
      },
    ])
  );

  runSimulation(nodes, sectorPositions);
  renderBubbles(nodes, colorScale);
  buildLegend(sectors, colorScale);

  const tableRows = data
    .slice()
    .sort((a, b) => d3.ascending(a.ticker, b.ticker));
  renderTable(tableRows);
};

const sanitizeRow = (d) => {
  const marketCap = d.marketCap === "" ? Number.NaN : +d.marketCap;
  const sector = d.sector || "Unknown";
  return {
    ticker: d.ticker,
    sector,
    fullName: d["full name"],
    marketCap,
    isEtf: sector === "ETF" || !Number.isFinite(marketCap),
    latestClose: Number.NaN,
  };
};

const init = () => {
  d3.csv("data/stock-descriptions.csv").then((raw) => {
    const data = raw.map(sanitizeRow);
    const tickers = data.map((d) => d.ticker).sort();

    Promise.all(tickers.map(loadHistory)).then((histories) => {
      const historyMap = new Map(histories.map((d) => [d.ticker, d.latestClose]));
      data.forEach((d) => {
        d.latestClose = historyMap.get(d.ticker);
      });
      render(data);
    });
  });
};

svg.on("click", () => selectTicker(null));
init();
